{
  "quiz_set": [
    {
      "id": 1,
      "type": "objective",
      "question": "question text",
      "options": ["option 1", "option 2", "option 3", "option 4", "option 5"],
      "key": 3,
      "hint": "hint text",
      "wrong_feedbacks": ["why option 1 is wrong", "why option 2 is wrong", "why option 4 is wrong", "why option 5 is wrong"]
    }
  ]
}
